-- =============================================================================
-- ARGOS FITNESS - SISTEMA DE GESTÃO DE ACADEMIA
-- MASSA DE DADOS FICTÍCIA (MySQL 8.0+)  -  executar APÓS o script DDL (script_academia.sql)
--
-- Data de referência da massa: 09/11/2026. Os status (pago, atrasado, pendente, ativa etc.)
-- foram calculados em relação a essa data.
--
-- PRIVACIDADE: todos os nomes, CPFs, CNPJs, e-mails e telefones são FICTÍCIOS, gerados
-- aleatoriamente (e-mails em domínios de exemplo). Nenhum dado real da organização foi usado.
--
-- PREMISSAS DE PORTE (ajustar aos números do item 1.1 - Contexto e porte, se forem outros):
--   Academia de porte médio, ~97 alunos com matrícula ativa, 6 instrutores, 6 planos,
--   catraca com leitor biométrico e ~12 meses de histórico comercial/financeiro.
--
-- COMO O VOLUME REAL JUSTIFICA CADA TABELA
--   PESSOA (126): 6 instrutores + 120 alunos (1 instrutor também é aluno, mostrando que uma
--     pessoa pode ter os dois perfis) + base de interessados.
--   TELEFONE (155): 1 celular por pessoa; ~30% têm um segundo número; alguns interessados sem telefone.
--   INSTRUTOR (6): quadro compatível com ~97 alunos ativos (~1 instrutor para 16 alunos); 1 admitido
--     em ago/2026 (só aparece em treinos posteriores à admissão); 1 sem especialidade (campo NULL).
--   ALUNO (121): 98 ativos, 6 com matrícula trancada, 10 que cancelaram e
--     8 cadastrados que nunca se matricularam (clientes sem compras).
--   PLANO (6): mensal, trimestral, semestral, anual, estudante e corporativo.
--   MATRICULA (131): {'encerrada': 28, 'ativa': 97, 'trancada': 6}. Inclui renovações/upgrades (aluno com
--     matrícula encerrada e outra ativa).
--   PAGAMENTO (712): uma parcela mensal por matrícula desde o início do contrato até a próxima
--     parcela a vencer. Status: {'pago': 577, 'cancelado': 11, 'atrasado': 25, 'pendente': 99}. Há 6 alunos inadimplentes
--     (2 a 3 parcelas atrasadas), parcelas canceladas por trancamento/cancelamento e primeira parcela
--     promocional em ~12% das matrículas.
--   ACESSO (971): passagens na catraca dos últimos 30 dias (10/10 a 09/11/2026) das matrículas ativas,
--     média de ~2.3 entradas/semana por aluno ativo, com perfis frequente, regular,
--     esporádico e raro. Sem registros aos domingos e nos feriados de 12/10 e 02/11; horários com picos
--     de manhã cedo, almoço e fim da tarde; sábados em horário reduzido.
--   EXERCICIO (50): catálogo cobrindo 12 grupos musculares/modalidades (inclui cardio e funcional).
--   TREINO (401): fichas A/B/C, ficha única ou full body, em ciclos de ~3 a 4 meses; cada aluno
--     matriculado tem o histórico de fichas encerradas e as fichas vigentes (DT_FIM NULL).
--   TREINO_EXERCICIO (2726): 5 a 8 exercícios por ficha, com séries, repetições, carga e intervalo
--     compatíveis com o objetivo. Exercícios sem carga (peso corporal e cardio) têm VR_CARGA NULL; no
--     cardio, QT_SERIES=1 e QT_REPETICOES=1 representam um bloco contínuo (duração no catálogo).
--   AVALIACAO_FISICA (212): avaliação de entrada e reavaliações a cada ~3 meses (algumas
--     faltas), com evolução de peso coerente com o objetivo. ALUNO.VR_PESO/VR_ALTURA guardam a medida mais recente.
--   FORNECEDOR (10): equipamentos, pesos, catraca, manutenção, limpeza, água, têxtil, climatização e peças.
--   EQUIPAMENTO (28): {'ativo': 23, 'em manutenção': 3, 'inativo': 2}. Modelos em manutenção têm ordem de manutenção
--     aberta (pendente/programada); inativos têm baixa registrada.
--   MANUTENCAO (83): {'concluída': 62, 'pendente': 2, 'programada': 19}. Preventivas periódicas (cardio a cada 3 meses, máquinas
--     a cada 6, racks anual) e corretivas esporádicas.
--   CONTAS_A_PAGAR (137): despesas recorrentes mensais (limpeza, água, ar-condicionado, software de
--     acesso), compras parceladas de equipamentos, reposições e serviços de manutenção. Status:
--     {'pago': 119, 'cancelado': 1, 'atrasado': 4, 'pendente': 13}.
--
-- OBSERVAÇÃO: a entidade ESTOQUE aparece no dicionário de dados, mas não existe no script DDL;
-- por isso não é populada aqui.
-- =============================================================================

USE db_academia;
SET NAMES utf8mb4;

-- Limpeza para permitir reexecução (reinicia os AUTO_INCREMENT)
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE CONTAS_A_PAGAR;
TRUNCATE TABLE MANUTENCAO;
TRUNCATE TABLE EQUIPAMENTO;
TRUNCATE TABLE FORNECEDOR;
TRUNCATE TABLE AVALIACAO_FISICA;
TRUNCATE TABLE TREINO_EXERCICIO;
TRUNCATE TABLE EXERCICIO;
TRUNCATE TABLE TREINO;
TRUNCATE TABLE ACESSO;
TRUNCATE TABLE PAGAMENTO;
TRUNCATE TABLE MATRICULA;
TRUNCATE TABLE PLANO;
TRUNCATE TABLE ALUNO;
TRUNCATE TABLE INSTRUTOR;
TRUNCATE TABLE TELEFONE;
TRUNCATE TABLE PESSOA;
SET FOREIGN_KEY_CHECKS = 1;

START TRANSACTION;

