-- EXERCICIO: 50 registros
INSERT INTO EXERCICIO (ID_EXERCICIO, NM_EXERCICIO, TP_GRUPO_MUSCULAR, DS_EXERCICIO) VALUES
    (1, 'Supino Reto com Barra', 'Peitoral', 'Deitado no banco, descer a barra até o peito e empurrar sem tirar o quadril do banco.'),
    (2, 'Supino Inclinado com Halteres', 'Peitoral', 'Banco a 30-45 graus; trabalha a porção superior do peitoral.'),
    (3, 'Supino Reto Articulado', 'Peitoral', 'Máquina com trajetória guiada, indicada para iniciantes.'),
    (4, 'Crucifixo Máquina (Peck Deck)', 'Peitoral', 'Manter cotovelos levemente flexionados e controlar a volta.'),
    (5, 'Crossover na Polia', 'Peitoral', 'Cruzar as mãos à frente do tronco, contraindo o peitoral.'),
    (6, 'Flexão de Braços', 'Peitoral', 'Corpo alinhado, descer até o cotovelo a 90 graus.'),
    (7, 'Desenvolvimento com Halteres', 'Ombros', 'Sentado, elevar os halteres acima da cabeça sem arquear a lombar.'),
    (8, 'Elevação Lateral', 'Ombros', 'Elevar os halteres até a altura dos ombros com leve flexão dos cotovelos.'),
    (9, 'Elevação Frontal', 'Ombros', 'Elevar o halter à frente até a altura dos ombros.'),
    (10, 'Desenvolvimento Articulado', 'Ombros', 'Máquina guiada para trabalho do deltoide.'),
    (11, 'Tríceps Pulley com Corda', 'Tríceps', 'Cotovelos junto ao corpo, estender e abrir a corda no final.'),
    (12, 'Tríceps Testa', 'Tríceps', 'Deitado, flexionar apenas os cotovelos com a barra W.'),
    (13, 'Tríceps Francês', 'Tríceps', 'Halter atrás da cabeça, estender os cotovelos.'),
    (14, 'Mergulho no Banco', 'Tríceps', 'Apoio de mãos no banco, descer e subir o corpo.'),
    (15, 'Puxada Alta Frontal', 'Costas', 'Puxar a barra até a altura do queixo, escápulas para baixo.'),
    (16, 'Remada Sentada na Polia', 'Costas', 'Tronco ereto, puxar o triângulo em direção ao abdômen.'),
    (17, 'Remada Curvada com Barra', 'Costas', 'Tronco inclinado, coluna neutra, puxar a barra ao abdômen.'),
    (18, 'Remada Unilateral com Halter', 'Costas', 'Apoio no banco, puxar o halter em direção ao quadril.'),
    (19, 'Barra Fixa', 'Costas', 'Pegada pronada, subir até o queixo passar da barra.'),
    (20, 'Rosca Direta com Barra', 'Bíceps', 'Cotovelos fixos ao lado do corpo.'),
    (21, 'Rosca Alternada com Halteres', 'Bíceps', 'Alternar os braços com supinação do punho.'),
    (22, 'Rosca Scott', 'Bíceps', 'Braços apoiados no banco Scott, amplitude completa.'),
    (23, 'Rosca Martelo', 'Bíceps', 'Pegada neutra, trabalha também o braquial.'),
    (24, 'Agachamento Livre', 'Quadríceps', 'Pés na largura dos ombros, descer até as coxas ficarem paralelas ao solo.'),
    (25, 'Leg Press 45°', 'Quadríceps', 'Pés na plataforma, descer sem tirar o quadril do encosto.'),
    (26, 'Cadeira Extensora', 'Quadríceps', 'Estender os joelhos contraindo o quadríceps.'),
    (27, 'Hack Machine', 'Quadríceps', 'Agachamento guiado com apoio nas costas.'),
    (28, 'Afundo com Halteres', 'Quadríceps', 'Passada longa alternada com halteres nas mãos.'),
    (29, 'Agachamento no Smith', 'Quadríceps', 'Agachamento guiado pela barra no Smith.'),
    (30, 'Mesa Flexora', 'Posterior de coxa', 'Deitado, flexionar os joelhos sem elevar o quadril.'),
    (31, 'Stiff com Barra', 'Posterior de coxa', 'Flexão de quadril com joelhos semiflexionados e coluna neutra.'),
    (32, 'Cadeira Flexora', 'Posterior de coxa', 'Sentado, flexionar os joelhos contra a resistência.'),
    (33, 'Elevação Pélvica', 'Glúteos', 'Costas apoiadas no banco, elevar o quadril contraindo o glúteo.'),
    (34, 'Cadeira Abdutora', 'Glúteos', 'Abrir as pernas contra a resistência da máquina.'),
    (35, 'Glúteo na Polia (Coice)', 'Glúteos', 'Chute para trás com tornozeleira na polia baixa.'),
    (36, 'Panturrilha em Pé', 'Panturrilha', 'Elevar os calcanhares com amplitude máxima.'),
    (37, 'Panturrilha Sentado', 'Panturrilha', 'Elevação de calcanhares com joelhos a 90 graus.'),
    (38, 'Abdominal Supra', 'Abdômen', 'Elevar o tronco sem puxar o pescoço.'),
    (39, 'Prancha Isométrica', 'Abdômen', 'Manter o corpo alinhado apoiado em antebraços e pontas dos pés.'),
    (40, 'Abdominal Infra no Banco', 'Abdômen', 'Elevar as pernas tirando o quadril do banco.'),
    (41, 'Abdominal na Polia', 'Abdômen', 'Ajoelhado, flexionar o tronco puxando a corda.'),
    (42, 'Esteira (caminhada/corrida)', 'Cardio', 'Aquecimento ou condicionamento em ritmo moderado.'),
    (43, 'Bicicleta Ergométrica', 'Cardio', 'Pedalada contínua com carga progressiva.'),
    (44, 'Elíptico', 'Cardio', 'Movimento contínuo de baixo impacto.'),
    (45, 'Remo Ergômetro', 'Cardio', 'Remada completa envolvendo pernas, tronco e braços.'),
    (46, 'Simulador de Escada', 'Cardio', 'Subida contínua em ritmo moderado a intenso.'),
